import { createHash } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { FIXED_SETTINGS_FILE, type HarnessKind, RUNTIME_STATE_DIRECTORY } from '@ferretry/fleet';
import { type HarnessWrapperSource, harnessHomeFromWrapper } from '../../../lib/session/transcript/index.ts';

/**
 * A digest of the fleet settings one wrapper launches its harness under.
 *
 * Two files carry them, and both are regenerated by `fy fleet apply` whenever the settings change:
 * the wrapper script itself (permission mode, the credential's environment, the fixed launch
 * arguments) and the fixed settings file in the harness home it exports. A process keeps whatever it
 * read at launch, so the digest recorded then and the digest taken now differ exactly when a relaunch
 * would run on something else.
 *
 * Nothing when the wrapper cannot be read: there is no evidence, and a stale-settings claim made
 * without any would be a guess. An absent fixed file is part of the evidence — a runtime with no fixed
 * layer — and digests as empty.
 */
export class FileLaunchSettingsDigest {
  constructor(
    private readonly wrappers: HarnessWrapperSource,
    /** The environment the wrapper runs in, which is the daemon's, so its home expands the same way. */
    private readonly environment: Readonly<Record<string, string | undefined>>,
  ) {}

  async digest(executable: string, harness: HarnessKind): Promise<string | undefined> {
    const wrapper = await this.wrappers.read(executable);
    if (wrapper === undefined) return undefined;
    const home = harnessHomeFromWrapper(wrapper, harness, this.environment);
    const fixed =
      home === undefined
        ? ''
        : await readFile(join(home, RUNTIME_STATE_DIRECTORY, FIXED_SETTINGS_FILE), 'utf8').catch(() => '');
    return createHash('sha256')
      .update(JSON.stringify([wrapper, fixed]), 'utf8')
      .digest('hex');
  }
}
